import {InjectionToken} from "@angular/core";
import {CreateItemData, CreateListData, List, UpdateItemData, UpdateListData} from "../models/data.model";
import {Observable} from "rxjs";

export const ITEM_REPOSITORY = new InjectionToken<ItemRepository>('ItemRepository');
export const LIST_REPOSITORY = new InjectionToken<ListRepository>('ListRepository');
export const IMAGE_REPOSITORY = new InjectionToken<ImageRepository>('ImageRepository');

export class DataRepositoryState {
  isDbOpen = false;
  error: string | null = null;
}

export interface ItemRepository {
  getState(): DataRepositoryState;

  createItemInList(listId: string, newItem: CreateItemData): Observable<string>;

  updateItem(id: string, item: UpdateItemData): Observable<number>;

  deleteItem(id: string): Observable<void>;
}

export interface ListRepository {
  getState(): DataRepositoryState;

  createList(param: CreateListData): Observable<string>;

  getAllLists(): Observable<List[]>;

  getListById(id: string): Observable<List>;

  updateList(id: string, list: UpdateListData): Observable<number>;

  deleteList(id: string): Observable<void>;
}

export interface ImageRepository {
  getState(): DataRepositoryState;

  createImage$(image: Blob): Observable<string>;

  createImage(image: Blob): Promise<string>;

  getImageById(id: string): Promise<Blob>;
}
